INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions, internal_category_id) VALUES ('6a8a2734-060c-5c23-8e9e-e63ccc9094dc'::uuid, 'b73d6285-bb19-5793-b250-d6374dd631ab'::uuid, 'Entreprise générale / travaux — réalisation de chantier', 'Mission de professionnels BTP portée par SOGEA Maroc, basé à Témara. Sogea Maroc conçoit et construit des ouvrages et des infrastructures pour le Maroc et l’Afrique de demain. La mission couvre typiquement les volets réalisation / accompagnement : Nos réalisations, Résidences Le Phare du Carrousel, Rabat 1.02.23 1 Fév 2023, Programme ISSA, Conseil et cadrage de la mission. SOGEA Maroc intervient à Témara, avec déplacement possible, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Notre équipe accompagne le client de la définition du besoin jusqu''à la réalisation de la prestation entreprise de construction, avec un interlocuteur dédié, un planning partagé et un reporting clair tout au long de la mission. Les options complémentaires (études, fournitures, suivi de chantier) sont proposées au cas par cas.', 'Construction Gros Oeuvre', 'https://sogea-maroc.com/wp-content/themes/vinci/static/assets/images/logo.svg', '["https://sogea-maroc.com/wp-content/uploads/sites/10/2024/01/annees-1950-chantiers-de-canaux-portes-dans-le-tadla-pour-lirrigation-1300x520.jpg", "https://sogea-maroc.com/wp-content/uploads/sites/10/2024/01/annees-1950-chantiers-de-canaux-portes-dans-le-tadla-pour-lirrigation-2000x1040.jpg", "https://sogea-maroc.com/wp-content/uploads/sites/10/2023/11/sogea-maroc-h-cmjn.png", "https://sogea-maroc.com/wp-content/uploads/sites/10/2024/01/2016-construction-de-la-gare-de-la-ligne-lgv-tanger-1-1012x520.jpg", "https://sogea-maroc.com/wp-content/themes/vinci/static/assets/images/logo.svg"]'::jsonb, '["Réalisation", "Accompagnement"]'::jsonb, '["Nos réalisations", "Résidences Le Phare du Carrousel, Rabat 1.02.23 1 Fév 2023", "Programme ISSA", "Conseil et cadrage de la mission", "Prestation adaptée au périmètre convenu", "Expertise Entreprise de construction"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Témara"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
