INSERT INTO public.services (id, user_id, title, description, category, cover, gallery, kinds, included, options, price_mode, amount, duration, zone_mode, cities, region, travel, remote, audiences, audience_other, missions, internal_category_id) VALUES ('01537857-a9ef-57e4-9810-7d1bb1cc7168'::uuid, 'c4850ba7-a81e-5d97-9ae7-7408cc07ef49'::uuid, 'Entreprise — offre clé en main', 'Mission de professionnels BTP portée par YORATECH SARL, basé à Marrakech. YORATECH SARL est un professionnel BTP basé à Marrakech, spécialisé en Entreprise. Référence citée : Réalisation prestations du contrôle externe des travaux des routes, autoroutes, infrastructures, etc…. La mission couvre typiquement les volets réalisation / accompagnement : Réalisation prestations du contrôle externe des travaux des routes,…, Améliorer la gestion et la rentabilité des projets, NOUS AVONS CONTRIBUE AUX REALISATION SUIVANTES:, Conseil et cadrage de la mission. YORATECH SARL intervient à Marrakech, avec déplacement possible, pour particuliers et entreprises, en mission nationale. Le tarif est établi sur devis, selon l''échelle et les phases confiées. Notre équipe accompagne le client de la définition du besoin jusqu''à la réalisation de la prestation entreprise, avec un interlocuteur dédié, un planning partagé et un reporting clair tout au long de la mission. Les options complémentaires (études, fournitures, suivi de chantier) sont proposées au cas par cas.', 'Construction Gros Oeuvre', 'http://www.yoratech.net/img/logo.png', '["http://www.yoratech.net/img/organigramme.jpg", "http://www.yoratech.net/img/Team/cadres.png", "http://www.yoratech.net/img/Team/administratif.png", "http://www.yoratech.net/img/Team/technicien.png", "http://www.yoratech.net/img/logo.png"]'::jsonb, '["Réalisation", "Accompagnement"]'::jsonb, '["Réalisation prestations du contrôle externe des travaux des routes,…", "Améliorer la gestion et la rentabilité des projets", "NOUS AVONS CONTRIBUE AUX REALISATION SUIVANTES:", "Conseil et cadrage de la mission", "Prestation adaptée au périmètre convenu", "Expertise Entreprise"]'::jsonb, '["Options sur devis"]'::jsonb, 'devis', NULL, NULL, 'villes', '["Marrakech"]'::jsonb, NULL, TRUE, FALSE, '["Particuliers", "Entreprises"]'::jsonb, NULL, '["National"]'::jsonb, (SELECT id FROM public.internal_categories WHERE code = '3.1.5' LIMIT 1));
